    { id: "2", email: "b@x.io", name: "B", phone: "", tags: ["beta"], updatedAt: 1 },
  ]);
  assert.deepEqual(summary, { total: 2, withPhone: 1, tagCounts: { vip: 1, beta: 2 } });
});
